function notify(text,error=false,hold=4000){clearTimeout(notifyTimer);const e=$('#status');e.textContent=text;e.classList.toggle('error',error);e.classList.add('show');if(!error)notifyTimer=setTimeout(()=>e.classList.remove('show'),hold);}
function resetTelemetryEvidence(){telemetryEvidence={generation,seq:0,frame:-1,receivedAt:0,windowFrames:0,gaps:0,valid:false,error:null};}
function acceptTelemetry(d){
 const t=d.telemetry,prev=telemetryEvidence,now=performance.now();let error=null,gaps=prev.generation===d.generation?prev.gaps:0;
 if(!t||t.schema!=='diddums.telemetry/1'||t.source!=='AudioWorkletProcessor')error='missing telemetry provenance';
 else if(!Number.isInteger(t.seq)||t.seq<1||!Number.isFinite(t.generatedAtFrame)||!Number.isFinite(t.windowStartFrame)||!Number.isFinite(t.windowEndFrame)||!Number.isFinite(t.windowFrames)||t.windowEndFrame!==t.generatedAtFrame||t.windowStartFrame>t.windowEndFrame||t.windowFrames!==t.windowEndFrame-t.windowStartFrame)error='invalid telemetry window';
 else if(prev.generation===d.generation&&prev.seq&&t.seq<=prev.seq)error='non-monotonic telemetry';
 else if(prev.generation===d.generation&&prev.seq&&t.seq>prev.seq+1)gaps+=t.seq-prev.seq-1;
 telemetryEvidence={generation:d.generation,seq:t?.seq||0,frame:t?.generatedAtFrame??-1,receivedAt:now,windowFrames:t?.windowFrames||0,gaps,valid:!error,error};
}
function updateLiveStatus(){
 const e=$('#liveStatus');if(!e)return;if(!playing){e.textContent=ctx?.state==='suspended'?'Paused':'Stopped';return;}
 const label=labPlaying?'Compare '+labPlaying.id:'DSP running',age=telemetryEvidence.receivedAt?performance.now()-telemetryEvidence.receivedAt:Infinity;
 if(!telemetryEvidence.valid){e.textContent=label+' · awaiting telemetry';return;}
 if(age>750){e.textContent=label+' · telemetry stale '+Math.round(age)+' ms';return;}
 const ms=ctx?.sampleRate&&telemetryEvidence.windowFrames?Math.round(telemetryEvidence.windowFrames/ctx.sampleRate*1000):0;
 e.textContent=(labPlaying?'Compare '+labPlaying.id:'Live DSP')+` · worklet #${telemetryEvidence.seq}${ms?` · ${ms} ms window`:''}${telemetryEvidence.gaps?` · ${telemetryEvidence.gaps} gap${telemetryEvidence.gaps===1?'':'s'}`:''}`;
}
