function parsePatternCodes(text){const pcs={C:0,D:2,E:4,F:5,G:7,A:9,B:11},tokens=String(text||'').replace(/\|/g,' ').split(/[\s,]+/).filter(Boolean);if(!tokens.length)throw new Error('Enter at least one note/rest token.');if(tokens.length>512)throw new Error('Local pattern is limited to 512 sixteenth-note steps.');return tokens.map((token,i)=>{if(['.','_','-'].includes(token))return null;const parts=token.split('@');if(parts.length>2)throw new Error(`Step ${i+1}: invalid velocity syntax`);const body=parts[0],velocity=parts[1]==null?1:Number(parts[1]);if(!(velocity>0&&velocity<=1.5))throw new Error(`Step ${i+1}: velocity must be >0 and ≤1.5`);let note;if(/^\d{1,3}$/.test(body))note=Number(body);else{const m=body.match(/^([A-Ga-g])([#b♯♭]?)(-?\d+)$/);if(!m)throw new Error(`Step ${i+1}: use MIDI 0–127, note names such as C3, or . for rest`);let pc=pcs[m[1].toUpperCase()];if(['#','♯'].includes(m[2]))pc++;if(['b','♭'].includes(m[2]))pc--;note=(Number(m[3])+1)*12+pc;}if(!(note>=0&&note<=127))throw new Error(`Step ${i+1}: MIDI note ${note} is outside 0–127`);return velocity===1?note:{note,velocity};});}
