function showPitchedSequence(id){const t=trackInfo(id);if(!t)return;$('#sequenceBox').hidden=false;$('#sequenceSummary').textContent='Local note pattern · private to this browser';$('#stepGrid').hidden=true;$('#pitchedSequenceEditor').hidden=false;const current=overrides[id]?.type==='patternCode'?overrides[id]:null,text=$('#sequenceText');text.value=current?.text||localStorage.getItem(localPatternKey(piece.id,id))||'';$('#applySequenceText').onclick=()=>{try{const raw=text.value.trim(),notes=parsePatternCodes(raw);overrides[id]={type:'patternCode',notes,text:raw};localStorage.setItem(localPatternKey(piece.id,id),raw);rebuildScore();showPitchedSequence(id);notify(`Local ${t.label} pattern applied · ${notes.length} steps · saved only in this browser.`);}catch(e){notify(e.message,true);}};$('#captureSequenceText').onclick=()=>{const bars=2,n=session.steps*bars,notes=Array(n).fill(null),seen=new Set();for(const e of session.events)if(e.track===id&&e.bar<bars){const step=Math.round(e.bar*session.steps+e.step);if(step>=0&&step<n&&!seen.has(step)){notes[step]=e.note;seen.add(step);}}text.value=formatPatternCodes(notes,session.steps);notify(`Captured the first ${bars} bars as monophonic MIDI-note codes; edit and Apply to make it your local repeating pattern.`);};$('#restoreSequence').onclick=()=>{delete overrides[id];localStorage.removeItem(localPatternKey(piece.id,id));rebuildScore();showPitchedSequence(id);notify('Restored authored score and removed the local browser pattern.');};}
