 patternUseChoices.set(id,use.value);const token=++patternNavigationSerial;setTab('listen');
 if(!audio||loadedId!==use.pieceId)await playPiece(use.pieceId);else if(!playing){await ctx.resume();audio.port.postMessage({type:'play',value:true});playing=true;updateTransport();}
